    dp[0][0] = 1

    # Fill the dp table
    for i in range(1, N + 1):
        for j in range(i, K + 1):
            for k in range(1, i):
                dp[i][j] = max(dp[i][j], dp[k][j - k] * k * int(num_str[k:i]))

    # The result is at dp[N][K]
